import jakarta.persistence.Entity;
import jakarta.persistence.Id;

@Entity
public class Gadget {

    @Id
    private Long id;

    private String name;

    private String color;
}

package com.example.shop.dto;

public record GadgetDto(
        Long id,
        String name
) {
}

